package com.ryanjei.orushio.pve.map;import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.domain.MapProfileId;import java.nio.file.*;import java.util.Map;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class YamlMapProfileRepositoryTest{@TempDir Path temp;@Test void 保存再読込削除(){YamlMapProfileRepository r=new YamlMapProfileRepository(temp);MapProfile p=MapProfileTest.complete("map-a");r.save(p);assertEquals(p.mapId(),r.find(p.mapId()).orElseThrow().mapId());r.delete(p.mapId());assertTrue(r.find(p.mapId()).isEmpty());}@Test void markerを再起動相当で維持し旧profileは空markerで読める()throws Exception{YamlMapProfileRepository r=new YamlMapProfileRepository(temp);MapProfile p=MapProfileTest.complete("map-a");Map<String,java.util.List<Cuboid>>areas=new java.util.HashMap<>(p.areas());areas.put("enemyZones",java.util.List.of(new Cuboid(0,0,0,10,100,10)));SpawnMarker marker=new SpawnMarker(java.util.UUID.randomUUID(),"enemyZones:0",new BlockPoint(2,64,2,90,0),true);MapProfile value=new MapProfile(p.mapId(),p.displayName(),false,p.templateDirectory(),p.points(),areas,p.createdAt(),java.util.List.of(marker));r.save(value);assertEquals(marker,new YamlMapProfileRepository(temp).find(p.mapId()).orElseThrow().spawnMarkers().getFirst());}@Test void Area外Markerを保存モデルとRepository読込の両方で拒否する()throws Exception{YamlMapProfileRepository r=new YamlMapProfileRepository(temp);MapProfile p=MapProfileTest.complete("map-a");Map<String,java.util.List<Cuboid>>areas=new java.util.HashMap<>(p.areas());areas.put("enemyZones",java.util.List.of(new Cuboid(0,0,0,10,100,10)));SpawnMarker marker=new SpawnMarker(java.util.UUID.randomUUID(),"enemyZones:0",new BlockPoint(2,64,2,0,0),true);assertThrows(IllegalArgumentException.class,()->new MapProfile(p.mapId(),p.displayName(),false,p.templateDirectory(),p.points(),areas,p.createdAt(),java.util.List.of(new SpawnMarker(marker.markerId(),marker.areaId(),new BlockPoint(99,64,99,0,0),true))));MapProfile normal=new MapProfile(p.mapId(),p.displayName(),false,p.templateDirectory(),p.points(),areas,p.createdAt(),java.util.List.of(marker));r.save(normal);Path file=temp.resolve("map-a/profile.yml");String content=Files.readString(file);Files.writeString(file,content.replace(marker.markerId()+",enemyZones:0,2,64,2",marker.markerId()+",enemyZones:0,99,64,99"));assertThrows(RuntimeException.class,()->new YamlMapProfileRepository(temp).find(p.mapId()));}@Test void schema異常を拒否()throws Exception{Path f=temp.resolve("map-a/profile.yml");Files.createDirectories(f.getParent());Files.writeString(f,"schemaVersion: \"99\"\n");assertThrows(RuntimeException.class,()->new YamlMapProfileRepository(temp).find(new MapProfileId("map-a")));}}
